// 1BRC Round A - fast C implementation
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <fcntl.h>
#include <unistd.h>
#include <sched.h>
#include <sys/stat.h>
#include <math.h>

#define MAXNAME 64
#define TBITS 12
#define TSIZE ((size_t)1 << TBITS)

typedef struct {
    uint64_t hash;
    uint16_t len;
    int16_t mn, mx;
    int64_t sum;
    uint32_t cnt;
    char name[MAXNAME];
} Entry;

typedef struct OEnt {
    struct OEnt *next;
    uint64_t hash;
    int len;
    int16_t mn, mx;
    int64_t sum;
    uint32_t cnt;
    char name[];
} OEnt;

typedef struct {
    off_t off0, off1;
    int fd;
    Entry *tab;
    OEnt *olist;
} Ctx;

static const uint64_t PRIME = 0x9E3779B97F4A7C15ULL;

static inline uint64_t hash_finalize(uint64_t h) {
    h ^= h >> 27;
    h *= 0x94D049BB133111EBULL;
    h ^= h >> 31;
    return h;
}

static inline uint64_t hassemi(uint64_t w) {
    uint64_t x = w ^ 0x3B3B3B3B3B3B3B3BULL;
    return (x - 0x0101010101010101ULL) & ~x & 0x8080808080808080ULL;
}

static inline void upd(Entry *e, int t10, uint64_t hh, const char *name, int len) {
    if (e->cnt == 0) {
        e->hash = hh;
        e->len = (uint16_t)len;
        e->mn = e->mx = (int16_t)t10;
        e->sum = t10;
        e->cnt = 1;
        memcpy(e->name, name, len);
    } else {
        e->sum += t10;
        e->cnt++;
        if (t10 < e->mn) e->mn = (int16_t)t10;
        else if (t10 > e->mx) e->mx = (int16_t)t10;
    }
}

static inline void upd_o(OEnt *e, int t10) {
    e->sum += t10;
    e->cnt++;
    if (t10 < e->mn) e->mn = (int16_t)t10;
    else if (t10 > e->mx) e->mx = (int16_t)t10;
}

static void process_block(const char *p, const char *end, Entry *tab, OEnt **olist) {
    while (p < end) {
        // hash + scan name up to ';'
        uint64_t h = 0x9E3779B97F4A7C15ULL ^ (uint8_t)p[0];
        const char *s = p;
        int idx = -1;
        for (;;) {
            uint64_t w;
            memcpy(&w, p, 8);
            uint64_t m = hassemi(w);
            if (__builtin_expect((m == 0), 1)) {
                h = (h ^ w) * PRIME;
                p += 8;
            } else {
                idx = __builtin_ctzll(m) >> 3;
                for (int i = 0; i < idx; i++) h = (h ^ (uint64_t)(uint8_t)p[i]) * PRIME;
                p += idx;
                break;
            }
        }
        int nlen = (int)(p - s);
        const char *tp = p + 1;
        int t10;
        char c0 = tp[0], c1 = tp[1], c2 = tp[2], c3 = tp[3];
        if (c1 >= '0' && c1 <= '9') {
            if (c2 == '.' && c3 >= '0' && c3 <= '9' && tp[4] == '\n') {
                t10 = (c0 - '0') * 100 + (c1 - '0') * 10 + (c3 - '0');
                p = tp + 5;
            } else goto slow;
        } else if (c1 == '.') {
            if (c2 >= '0' && c2 <= '9' && tp[3] == '\n') {
                t10 = (c0 - '0') * 10 + (c2 - '0');
                p = tp + 4;
            } else goto slow;
        } else goto slow;
        if (c0 == '-') t10 = -t10;
        else if (__builtin_expect(c0 == '+', 0)) goto done_sign;
        else goto have;
    done_sign:
        goto have;
    have: {}
        // update table
        if (__builtin_expect(nlen < MAXNAME, 1)) {
            uint64_t hh = hash_finalize(h);
            size_t i = (size_t)hh & (TSIZE - 1);
            for (;;) {
                Entry *e = &tab[i];
                if (e->len == 0) { upd(e, t10, hh, s, nlen); break; }
                if (e->hash == hh && e->len == (uint16_t)nlen &&
                    memcmp(e->name, s, nlen) == 0) { upd(e, t10, hh, s, nlen); break; }
                i = (i + 1) & (TSIZE - 1);
            }
        } else {
            // overflow list (names >= MAXNAME)
            OEnt *e;
            for (e = *olist; e; e = e->next)
                if (e->len == nlen && memcmp(e->name, s, nlen) == 0) break;
            if (!e) {
                e = malloc(sizeof(OEnt) + nlen);
                e->next = *olist; *olist = e;
                e->len = nlen; e->mn = e->mx = 0; e->sum = 0; e->cnt = 0;
                memcpy(e->name, s, nlen);
            }
            upd_o(e, t10);
        }
        continue;
    slow: {
            const char *nl = memchr(tp, '\n', (size_t)(end - tp));
            char tmp[40];
            size_t L = nl ? (size_t)(nl - tp) : 0;
            if (L > 30) L = 30;
            memcpy(tmp, tp, L);
            tmp[L] = 0;
            double td = strtod(tmp, NULL);
            t10 = (int)lrint(td * 10.0);
            p = nl ? nl + 1 : end;
            if (__builtin_expect(nlen < MAXNAME, 1)) {
                uint64_t hh = hash_finalize(h);
                size_t i = (size_t)hh & (TSIZE - 1);
                for (;;) {
                    Entry *e = &tab[i];
                    if (e->len == 0) { e->hash = hh; e->len = (uint16_t)nlen; e->cnt = 0; memcpy(e->name, s, nlen); upd(e, t10, hh, s, nlen); break; }
                    if (e->hash == hh && e->len == (uint16_t)nlen && memcmp(e->name, s, nlen) == 0) { upd(e, t10, hh, s, nlen); break; }
                    i = (i + 1) & (TSIZE - 1);
                }
            } else {
                OEnt *e;
                for (e = *olist; e; e = e->next)
                    if (e->len == nlen && memcmp(e->name, s, nlen) == 0) break;
                if (!e) {
                    e = malloc(sizeof(OEnt) + nlen);
                    e->next = *olist; *olist = e;
                    e->len = nlen; e->mn = 0; e->mx = 0; e->sum = 0; e->cnt = 0;
                    memcpy(e->name, s, nlen);
                }
                upd_o(e, t10);
            }
        }
    }
}

static void *worker(void *arg) {
    Ctx *c = (Ctx *)arg;
    size_t bsz = (size_t)1 << 22; // 4MB
    char *buf = aligned_alloc(64, bsz + 128);
    memset(buf + bsz, 0, 128);
    off_t pos = c->off0;
    size_t carry = 0;
    while (pos < c->off1) {
        size_t want = bsz - carry;
        off_t rem = c->off1 - pos;
        if (rem < (off_t)want) want = (size_t)rem;
        ssize_t r = pread(c->fd, buf + carry, want, pos);
        if (r <= 0) break;
        pos += r;
        size_t have = carry + (size_t)r;
        if (pos < c->off1) {
            char *lnl = memrchr(buf, '\n', have);
            if (!lnl) { carry = have; continue; } // won't happen for 4MB blocks
            process_block(buf, lnl + 1, c->tab, &c->olist);
            carry = have - (size_t)(lnl + 1 - buf);
            if (carry) memmove(buf, lnl + 1, carry);
        } else {
            process_block(buf, buf + have, c->tab, &c->olist);
            carry = 0;
        }
    }
    free(buf);
    return NULL;
}

static int cmpent(const void *a, const void *b) {
    const Entry *x = (const Entry *)a, *y = (const Entry *)b;
    size_t m = x->len < y->len ? x->len : y->len;
    int c = memcmp(x->name, y->name, m);
    if (c) return c;
    return (int)x->len - (int)y->len;
}

static int nthreads_override = 0;

int main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: sol <file>\n"); return 1; }
    if (getenv("BRC_THREADS")) nthreads = atoi(getenv("BRC_THREADS"));
    int fd = open(argv[1], O_RDONLY);
    if (fd < 0) { perror("open"); return 1; }
    struct stat st;
    if (fstat(fd, &st) < 0) { perror("fstat"); return 1; }
    off_t size = st.st_size;

    int nthreads = 4;
    cpu_set_t cs;
    CPU_ZERO(&cs);
    if (sched_getaffinity(0, sizeof(cs), &cs) == 0) {
        int n = CPU_COUNT(&cs);
        if (n > 0) nthreads = n;
    }
    if (nthreads < 1) nthreads = 1;
    if ((size_t)nthreads * 65536 > (size_t)size) nthreads = 1;
    if (nthreads > 32) nthreads = 32;

    Entry *tables = calloc((size_t)nthreads * TSIZE, sizeof(Entry));
    Ctx *ctxs = calloc((size_t)nthreads, sizeof(Ctx));
    pthread_t *tids = calloc((size_t)nthreads, sizeof(pthread_t));
    int *fds = calloc((size_t)nthreads, sizeof(int));

    for (int i = 0; i < nthreads; i++) {
        fds[i] = (i == 0) ? fd : open(argv[1], O_RDONLY);
        off_t a = size * i / nthreads;
        off_t b = size * (i + 1) / nthreads;
        if (a > 0) {
            // advance to next newline
            char tmp[512];
            off_t scan = a;
            while (scan < b && scan < size) {
                size_t want = (size_t)(b - scan);
                if (want > sizeof(tmp)) want = sizeof(tmp);
                ssize_t r = pread(fds[i], tmp, want, scan);
                if (r <= 0) break;
                char *nl = memchr(tmp, '\n', (size_t)r);
                if (nl) { scan += (nl - tmp) + 1; break; }
                scan += (size_t)r;
            }
            if (scan > b) scan = b;
            a = scan;
        }
        ctxs[i].off0 = a;
        ctxs[i].off1 = b;
        ctxs[i].fd = fds[i];
        ctxs[i].tab = tables + (size_t)i * TSIZE;
        ctxs[i].olist = NULL;
    }

    for (int i = 1; i < nthreads; i++)
        pthread_create(&tids[i], NULL, worker, &ctxs[i]);
    worker(&ctxs[0]);
    for (int i = 1; i < nthreads; i++)
        pthread_join(tids[i], NULL);

    // merge into table 0
    Entry *gtab = tables;
    int olen = 0;
    for (int t = 1; t < nthreads; t++) {
        Entry *tab = tables + (size_t)t * TSIZE;
        for (size_t i = 0; i < TSIZE; i++) {
            Entry *e = &tab[i];
            if (e->cnt == 0) continue;
            size_t j = (size_t)e->hash & (TSIZE - 1);
            for (;;) {
                Entry *g = &gtab[j];
                if (g->cnt == 0) { *g = *e; break; }
                if (g->hash == e->hash && g->len == e->len &&
                    memcmp(g->name, e->name, e->len) == 0) {
                    if (e->mn < g->mn) g->mn = e->mn;
                    if (e->mx > g->mx) g->mx = e->mx;
                    g->sum += e->sum;
                    g->cnt += e->cnt;
                    break;
                }
                j = (j + 1) & (TSIZE - 1);
            }
        }
    }
    for (size_t i = 0; i < TSIZE; i++)
        if (gtab[i].cnt) olen++;

    Entry *out = malloc(sizeof(Entry) * (size_t)(olen + 1));
    int k = 0;
    for (size_t i = 0; i < TSIZE; i++)
        if (gtab[i].cnt) out[k++] = gtab[i];
    qsort(out, (size_t)olen, sizeof(Entry), cmpent);

    // build output
    size_t cap = (size_t)olen * 96 + 16;
    char *ob = malloc(cap);
    char *o = ob;
    *o++ = '{';
    for (int i = 0; i < olen; i++) {
        Entry *e = &out[i];
        memcpy(o, e->name, e->len); o += e->len;
        *o++ = '=';
        o += sprintf(o, "%.1f", (double)e->mn / 10.0);
        *o++ = '/';
        // mean: replicate reference rounding exactly
        double d = (double)e->sum / (double)e->cnt;
        double scaled = d / 10.0 * 10.0;
        double r = (scaled >= 0.0) ? floor(scaled + 0.5) : ceil(scaled - 0.5);
        double v = r / 10.0;
        if (v == 0.0) v = 0.0;
        o += sprintf(o, "%.1f", v);
        *o++ = '/';
        o += sprintf(o, "%.1f", (double)e->mx / 10.0);
        if (i + 1 < olen) { *o++ = ','; *o++ = ' '; }
    }
    *o++ = '}';
    fwrite(ob, 1, (size_t)(o - ob), stdout);
    return 0;
}

