            while (scan < size) {
                size_t want = (size_t)(b - scan);
                if (want == 0) { scan = b; break; }
                if (want > sizeof(tmp)) want = sizeof(tmp);
                ssize_t r = pread(fdi, tmp, want, scan);
                if (r <= 0) break;
                char *nl = (char *)memchr(tmp, '\n', (size_t)r);
                if (nl) { scan += (nl - tmp) + 1; break; }
                scan += (size_t)r;
            }
            if (scan > b) scan = b;
            a = scan;
        }
        ctxs[i].off0 = a;
        ctxs[i].off1 = b;
        ctxs[i].fd = fdi;
        ctxs[i].tab = tables + (size_t)i * TSIZE;
        ctxs[i].olist = NULL;
    }

    for (int i = 1; i < nthreads; i++)
        pthread_create(&tids[i], NULL, worker, &ctxs[i]);
    worker(&ctxs[0]);
    for (int i = 1; i < nthreads; i++)
