                    if (e->mx > g->mx) g->mx = e->mx;
                    g->sum += e->sum;
                    g->cnt += e->cnt;
                    break;
                }
                j = (j + 1) & (TSIZE - 1);
            }
        }
    }
    for (size_t i = 0; i < TSIZE; i++)
        if (gtab[i].cnt) olen++;

    // overflow entries appended
    for (int t = 0; t < nthreads; t++) {
        for (OEnt *e = ctxs[t].olist; e; e = e->next) olen++;
    }

    Entry *out = (Entry *)malloc(sizeof(Entry) * (size_t)(olen + 1));
    int k = 0;
