import subprocess,time,pathlib,statistics
expected=pathlib.Path('/work/base.out').read_bytes()
candidates={'current':None,'chunk22':None}
import os
# Use compiled binaries directly (same code run.sh embeds / pre-compiled).
commands={'current':['/work/read-1-1'],'chunk22':['/work/t-2-22']}
results={k:[] for k in commands}
for r in range(11):
 for k in (['current','chunk22'] if r%2==0 else ['chunk22','current']):
  start=time.perf_counter()
  out=subprocess.check_output(commands[k]+['/work/1b.txt'])
  elapsed=time.perf_counter()-start
  assert out==expected,(k,r)
  if r>=1:results[k].append(elapsed)
  print(k,'run',r,round(elapsed,4),flush=True)
for k,v in results.items():print(k,'median',round(statistics.median(v),4),'min',round(min(v),4),flush=True)

