#!/bin/sh
set -eu
ROOT=/work/submission
if [ ! -x "$ROOT/read-v1" ]; then
  g++ -x c++ -std=c++17 -O3 -march=native -pthread -DSTREAMS=2 -DTBITS=12 -DTEMP=1 -DCOMPARE=1 -DIO=2 -DOWNFD=1 -DFADVICE=1 -o "$ROOT/read-v1.tmp" - <<'CPP_SOURCE'
#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cstdint>
#include <string>
#include <vector>
#include <thread>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <immintrin.h>
#include <atomic>
#ifndef IO
#define IO 0
#endif
#ifndef CHUNK
#define CHUNK 22
#endif
#ifndef ADVICE
#define ADVICE 0
#endif
#ifndef OWNFD
#define OWNFD 0
#endif
#ifndef FADVICE
#define FADVICE 0
#endif
using namespace std;
#ifndef TBITS
#define TBITS 12
#endif
#ifndef STREAMS
#define STREAMS 1
