 FILE*f=fopen(argv[1],"wb");if(!f)return 3;char *buf=new char[8<<20];setvbuf(f,buf,_IOFBF,8<<20);
 uint64_t rng=strtoull(argv[4],0,10);auto next=[&](){rng^=rng<<13;rng^=rng>>7;rng^=rng<<17;return rng;};
